// Generated by vibelang from src/internal/machineName.ts; the migrate flow writes it again with each batch.
/**
 * Derives a vendor machine name from a session key.
 *
 * @since 0.1.0
 */
import { sessionSlug } from "./sessionSlug.js";
/**
 * The lowercase, dot- and underscore-free name `prefix` plus the session slug.
 *
 * @category utils
 * @since 0.1.0
 */
export const machineName = (prefix, session) => `${prefix}${sessionSlug(session)}`.toLowerCase().replaceAll(/[._]/g, "-");
